import React, { useEffect, useState } from "react";
import {
  Box,
  Flex,
  Heading,
  Text,
  Button,
  Avatar,
  HStack,
  VStack,
  SimpleGrid,
  Spinner,
  Alert,
  AlertIcon,
} from "@chakra-ui/react";
import { Link as RouterLink, useNavigate } from "react-router-dom";
import { FaGithub, FaPlus, FaUsers } from "react-icons/fa";
import API from "../api";

const Dashboard = () => {
  const [user, setUser] = useState(null);
  const [workspaces, setWorkspaces] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const navigate = useNavigate();

  // ✨ Gemini Color Tokens
  const bg = "transparent";
  const cardBg = "rgba(26, 26, 31, 0.8)";
  const borderColor = "rgba(255, 255, 255, 0.05)";
  const textPrimary = "white";
  const textSecondary = "rgba(255, 255, 255, 0.7)";
  const textTertiary = "rgba(255, 255, 255, 0.5)";

  useEffect(() => {
    let isMounted = true;

    const fetchData = async () => {
      try {
        setLoading(true);
        setError(null);

        const [userRes, wsRes] = await Promise.all([
          API.get("/auth/user"),
          API.get("/workspaces"),
        ]);

        if (!isMounted) return;

        setUser(userRes.data);
        setWorkspaces(Array.isArray(wsRes.data) ? wsRes.data : []);
      } catch (err) {
        if (!isMounted) return;

        if (err.response?.status === 401) {
          // Not authenticated – send back to login
          navigate("/", { replace: true });
          return;
        }

        setError("Failed to load dashboard data. Please try again.");
      } finally {
        if (isMounted) {
          setLoading(false);
        }
      }
    };

    fetchData();

    return () => {
      isMounted = false;
    };
  }, [navigate]);

  const recentWorkspaces = workspaces.slice(0, 3);

  return (
    <Box minH="100vh" bg={bg} py={10} px={4}>
      <Box maxW="6xl" mx="auto">
        {/* ✨ Header Section */}
        <Flex justify="space-between" align="center" mb={8}>
          <HStack spacing={3}>
            <Avatar
              size="md"
              name={user?.displayName || user?.username || "User"}
              src={user?.avatar}
            />
            <VStack align="start" spacing={0}>
              <Text fontSize="sm" color={textSecondary}>
                Welcome back,
              </Text>
              <Heading size="md" color={textPrimary}>
                {user?.displayName || user?.username || "Collaborator"}
              </Heading>
            </VStack>
          </HStack>

          {/* ✨ Action Buttons */}
          <HStack spacing={3}>
            <Button
              as="a"
              href={`${process.env.REACT_APP_API_URL || "http://localhost:5000"}/api/auth/logout`}
              bg="rgba(239, 68, 68, 0.2)"
              border="1px solid rgba(239, 68, 68, 0.3)"
              color="#ef4444"
              size="sm"
              transition="all 0.2s ease"
              _hover={{
                bg: "rgba(239, 68, 68, 0.3)",
                boxShadow: "0 0 20px rgba(239, 68, 68, 0.2)",
              }}
            >
              Logout
            </Button>
            <Button
              as={RouterLink}
              to="/workspaces"
              bg="rgba(59, 130, 246, 0.15)"
              border="1px solid rgba(59, 130, 246, 0.3)"
              color="#3b82f6"
              leftIcon={<FaUsers />}
              transition="all 0.2s ease"
              _hover={{
                bg: "rgba(59, 130, 246, 0.25)",
                boxShadow: "0 0 30px rgba(59, 130, 246, 0.3)",
              }}
            >
              View workspaces
            </Button>
            <Button
              as={RouterLink}
              to="/repos"
              bg="rgba(255, 255, 255, 0.05)"
              border="1px solid rgba(255, 255, 255, 0.1)"
              color="white"
              leftIcon={<FaGithub />}
              transition="all 0.2s ease"
              _hover={{
                bg: "rgba(255, 255, 255, 0.1)",
                boxShadow: "0 0 20px rgba(0, 217, 255, 0.2)",
              }}
            >
              GitHub repos
            </Button>
          </HStack>
        </Flex>

        {loading && (
          <Flex justify="center" align="center" py={20}>
            <Spinner size="lg" color="#3b82f6" />
          </Flex>
        )}

        {!loading && error && (
          <Alert
            status="error"
            mb={6}
            bg="rgba(239, 68, 68, 0.2)"
            borderColor="rgba(239, 68, 68, 0.3)"
          >
            <AlertIcon color="#ef4444" />
            <Text color={textPrimary}>{error}</Text>
          </Alert>
        )}

        {!loading && !error && (
          <SimpleGrid columns={{ base: 1, md: 2 }} spacing={6}>
            {/* ✨ Overview Card */}
            <Box
              bg={cardBg}
              borderWidth="1px"
              borderColor={borderColor}
              rounded="16px"
              p={6}
              boxShadow="0 8px 32px rgba(0, 0, 0, 0.5), inset 0 1px 0 rgba(255, 255, 255, 0.1)"
              className="glassmorphic-card"
              style={{ backdropFilter: "blur(12px)" }}
              transition="all 0.2s ease"
              _hover={{
                bg: "rgba(26, 26, 31, 0.9)",
                borderColor: "rgba(255, 255, 255, 0.1)",
                transform: "scale(1.02)",
                boxShadow:
                  "0 8px 32px rgba(0, 0, 0, 0.6), inset 0 1px 0 rgba(255, 255, 255, 0.1)",
              }}
            >
              <VStack align="start" spacing={4}>
                <Heading size="md" color={textPrimary}>
                  Your workspace hub
                </Heading>
                <Text color={textSecondary} fontSize="sm">
                  Jump back into your recent workspaces, collaborate with your
                  team in real-time, and keep repos, tasks, notes, and chat all
                  in one place.
                </Text>
                <HStack spacing={3}>
                  <Button
                    as={RouterLink}
                    to="/workspaces"
                    bg="rgba(59, 130, 246, 0.2)"
                    border="1px solid rgba(59, 130, 246, 0.3)"
                    color="#3b82f6"
                    leftIcon={<FaPlus />}
                    transition="all 0.2s ease"
                    _hover={{
                      bg: "rgba(59, 130, 246, 0.3)",
                      boxShadow: "0 0 30px rgba(59, 130, 246, 0.3)",
                    }}
                  >
                    New workspace
                  </Button>
                  <Button
                    as={RouterLink}
                    to="/repos"
                    bg="rgba(255, 255, 255, 0.05)"
                    border="1px solid rgba(255, 255, 255, 0.1)"
                    color="white"
                    leftIcon={<FaGithub />}
                    transition="all 0.2s ease"
                    _hover={{
                      bg: "rgba(255, 255, 255, 0.1)",
                      boxShadow: "0 0 20px rgba(0, 217, 255, 0.2)",
                    }}
                  >
                    Connect repos
                  </Button>
                </HStack>
              </VStack>
            </Box>

            {/* ✨ Recent Workspaces Card */}
            <Box
              bg={cardBg}
              borderWidth="1px"
              borderColor={borderColor}
              rounded="16px"
              p={6}
              boxShadow="0 8px 32px rgba(0, 0, 0, 0.5), inset 0 1px 0 rgba(255, 255, 255, 0.1)"
              className="glassmorphic-card"
              style={{ backdropFilter: "blur(12px)" }}
              transition="all 0.2s ease"
              _hover={{
                bg: "rgba(26, 26, 31, 0.9)",
                borderColor: "rgba(255, 255, 255, 0.1)",
                transform: "scale(1.02)",
              }}
            >
              <VStack align="stretch" spacing={4}>
                <Heading size="sm" color={textPrimary}>
                  Recent workspaces
                </Heading>
                {recentWorkspaces.length === 0 ? (
                  <Text fontSize="sm" color={textTertiary}>
                    You don&apos;t have any workspaces yet. Create one to get
                    started.
                  </Text>
                ) : (
                  recentWorkspaces.map((ws) => (
                    <Box
                      key={ws._id}
                      borderWidth="1px"
                      borderColor="rgba(255, 255, 255, 0.05)"
                      rounded="12px"
                      p={3}
                      bg="rgba(255, 255, 255, 0.02)"
                      transition="all 0.2s ease"
                      _hover={{
                        bg: "rgba(59, 130, 246, 0.15)",
                        borderColor: "rgba(59, 130, 246, 0.3)",
                        cursor: "pointer",
                        boxShadow: "0 0 20px rgba(59, 130, 246, 0.2)",
                      }}
                      as={RouterLink}
                      to={`/workspaces/${ws._id}`}
                    >
                      <HStack justify="space-between" align="start">
                        <VStack align="start" spacing={1}>
                          <Text fontWeight="semibold" color={textPrimary}>
                            {ws.name}
                          </Text>
                          {ws.description && (
                            <Text
                              fontSize="sm"
                              color={textSecondary}
                              noOfLines={2}
                            >
                              {ws.description}
                            </Text>
                          )}
                        </VStack>
                        {ws.currentUserRole && (
                          <Text
                            fontSize="xs"
                            textTransform="uppercase"
                            color="rgba(255, 255, 255, 0.5)"
                            bg="rgba(59, 130, 246, 0.2)"
                            px={2}
                            py={1}
                            borderRadius="6px"
                            fontWeight="600"
                          >
                            {ws.currentUserRole}
                          </Text>
                        )}
                      </HStack>
                    </Box>
                  ))
                )}
              </VStack>
            </Box>
          </SimpleGrid>
        )}
      </Box>
    </Box>
  );
};

export default Dashboard;
