import React, { useEffect } from "react";
import { BrowserRouter as Router, Routes, Route } from "react-router-dom";
import Login from "./pages/Login";
import Dashboard from "./pages/Dashboard";
import Repositories from "./pages/Repositories";
import Workspaces from "./pages/Workspaces";
import Workspace from "./pages/Workspace";
// Team Collaboration: Handle workspace invitation acceptance
import InvitationHandler from "./pages/InvitationHandler";
import { socket } from "./socket";

function App() {
  useEffect(() => {
    // Auto-connect socket on app load
    if (!socket.connected) {
      socket.connect();
      console.log("Socket connecting...");
    }

    // Handle socket connection events
    socket.on("connect", () => {
      console.log("Socket connected:", socket.id);
    });

    socket.on("disconnect", () => {
      console.log("Socket disconnected");
    });

    socket.on("connect_error", (error) => {
      console.error("Socket connection error:", error);
    });

    // Cleanup on unmount
    return () => {
      socket.off("connect");
      socket.off("disconnect");
      socket.off("connect_error");
    };
  }, []);

  return (
    <Router>
      <Routes>
        <Route path="/" element={<Login />} />
        <Route path="/dashboard" element={<Dashboard />} />
        <Route path="/repos" element={<Repositories />} />
        <Route path="/workspaces" element={<Workspaces />} />
        <Route path="/workspaces/:id" element={<Workspace />} />
        {/* Team Collaboration: Invitation endpoint for accepting workspace invites */}
        <Route path="/invite/:token" element={<InvitationHandler />} />
      </Routes>
    </Router>
  );
}

export default App;
